<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';
if(user_id()||admin_id()) redirect(user_id()?'dashboard.php':'admin/index.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$login=trim((string)post('login'));$pass=(string)post('password');$u=dbone('SELECT * FROM users WHERE username=? OR email=? LIMIT 1',[$login,$login]);$a=dbone('SELECT * FROM admins WHERE username=? OR email=? LIMIT 1',[$login,$login]);if($u&&password_verify($pass,$u['password'])){$_SESSION['user_id']=(int)$u['id'];unset($_SESSION['admin_id']);dbq('UPDATE users SET login_time=NOW() WHERE id=?',[$u['id']]);log_action('login','User login');redirect('dashboard.php');}if($a&&password_verify($pass,$a['password'])){$_SESSION['admin_id']=(int)$a['id'];unset($_SESSION['user_id']);dbq('UPDATE admins SET login_time=NOW() WHERE id=?',[$a['id']]);log_action('admin_login','Administrator login');redirect('admin/index.php');}$error='Invalid username/email or password.';}
$title='Login';require __DIR__.'/includes/header.php';?><div class="login card"><h1>Sign in</h1><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="field"><label>Username or email</label><input name="login" required autofocus></div><div class="field"><label>Password</label><input type="password" name="password" required></div><br><button class="btn">Sign in</button></form><p class="muted">New user? <a href="register.php">Create an account</a></p></div><?php require __DIR__.'/includes/footer.php';?>
